// NYKO Earth for the hero sky: the art as a pure module, so the hero can spin it and the brand script can
// write the static nyko-earth.svg from the same source. No DOM, no randomness: the same angles give the
// same paths. Only dependency: d3-geo (already a site dependency, shared with the Travel Log globe).
//
//   import { earthLayers, EARTH } from '../../brand/round-2-iconography/earth-art';
//   const L = earthLayers(lon);            // path data in the -64..64 box, disc radius 60, origin at the centre
//   new Path2D(L.land) …                   // fill order: ocean disc, grid (stroke), land, ice, clouds
//
// The coastline is baked below at low detail (Natural Earth 110m, coarsened on the sphere, small islands
// dropped) by gen_earth.mjs, so it stays put while the globe turns: no per-frame simplification wobble.
// Edges are rounded at draw time with quadratic curves through the edge midpoints, which never leave the
// points' hull, so nothing crosses r = 60. Unlit: the hero shades the night side from the sun's direction.
import { geoOrthographic, geoPath, geoCircle } from 'd3-geo';

export const EARTH = {
  HALF: 64,            // viewBox half-size
  R: 60,               // disc radius
  REST_LON: -100,      // resting pose: centred 28°N 100°W (North America, Seattle upper-left)
  LAT: 28,             // fixed tilt toward the viewer; only the longitude turns
  ocean: ['#2F8BD8', '#1C5FAE'] as const,   // gradient from upper-left to lower-right (x/y ±42)
  land: '#5E9E4A',                          // illustration green; not --nominal, no ember
  ice: ['#E2F6F8', '#8FD3E3'] as const,     // glacial cyan, gradient from y = -60 (pole) to y = -30
  cloud: '#F6F8FC',
  grid: '#BFE3FF', gridAlpha: 0.22,         // faint engineering graticule over the ocean, every 30°
};

type Ring = [number, number][];
type Poly = Ring[];

// Clouds: soft blobs of overlapping puffs [lon, lat, radius°]. Same winding, one path, so they union.
