const ICE: Poly[] = [[[[-27.1,83.5],[-17.7,80.1],[-21.7,76.6],[-22.3,72.6],[-27.7,68.5],[-36.4,66],[-42.8,62.7],[-51.6,63.6],[-54,67.2],[-54.4,70.8],[-57.3,74.7],[-71.4,77],[-67.1,80.5],[-27.1,83.5]]]];
// </land>

const fmt = (v: number) => String(Math.round(v * 10) / 10);
function smooth(pts: Ring): string {
  // Drop near-duplicates (the limb clip packs points tightly), then round off through edge midpoints.
  const p: Ring = [];
  for (const q of pts) if (!p.length || Math.hypot(q[0] - p[p.length - 1][0], q[1] - p[p.length - 1][1]) >= 1.2) p.push(q);
  while (p.length > 3 && Math.hypot(p[0][0] - p[p.length - 1][0], p[0][1] - p[p.length - 1][1]) < 1.2) p.pop();
  if (p.length < 3) return '';
  const n = p.length, mid = (i: number) => [(p[i % n][0] + p[(i + 1) % n][0]) / 2, (p[i % n][1] + p[(i + 1) % n][1]) / 2];
  const m0 = mid(0);
  let out = `M${fmt(m0[0])} ${fmt(m0[1])}`;
  for (let i = 1; i <= n; i++) { const c = p[i % n], m = mid(i); out += `Q${fmt(c[0])} ${fmt(c[1])} ${fmt(m[0])} ${fmt(m[1])}`; }
  return out + 'Z';
}

function projector(lon: number) {
  const proj = geoOrthographic().rotate([-lon, -EARTH.LAT]).scale(EARTH.R).translate([0, 0]).clipAngle(90).precision(0);  // no resampling: all geometry is pre-spaced
  const filled = (geoms: object[]) => {
    let out = '', ring: Ring = [];
    const ctx = {
      moveTo(x: number, y: number) { ring = [[x, y]]; },
      lineTo(x: number, y: number) { ring.push([x, y]); },
      closePath() { out += smooth(ring); ring = []; },
      arc() {},
    };
    const path = geoPath(proj, ctx as any);
    for (const g of geoms) path(g as any);
    return out;
  };
  const stroked = (g: object) => {
    let out = '';
    const ctx = {
      moveTo(x: number, y: number) { out += `M${fmt(x)} ${fmt(y)}`; },
      lineTo(x: number, y: number) { out += `L${fmt(x)} ${fmt(y)}`; },
      closePath() { out += 'Z'; },
      arc() {},
    };
    geoPath(proj, ctx as any)(g as any);
    return out;
  };
  return { filled, stroked };
}

const poly = (coordinates: Poly) => ({ type: 'Polygon', coordinates });
const puff = ([lon, lat, r]: [number, number, number]) => geoCircle().center([lon, lat]).radius(r).precision(8)();
// Built once: the geometry never changes, only the view. Clouds shift by adding to their longitudes.
const LAND_G = LAND.map(poly);
const ICE_G = [...CAP.map(puff), ...ICE.map(poly)];
const CLOUD_G = PUFFS.map(puff) as { type: string; coordinates: number[][][] }[];
const shifted = (dl: number) => (dl ? CLOUD_G.map((g) => ({ type: g.type, coordinates: g.coordinates.map((r) => r.map(([a, b]) => [a + dl, b])) })) : CLOUD_G);
// Graticule every 30°, densely sampled (every 2°) so no resampling is needed and the lines stay smooth.
const span = (a: number, b: number) => Array.from({ length: Math.round((b - a) / 2) + 1 }, (_, i) => a + i * 2);
const GRID = {
  type: 'MultiLineString',
  coordinates: [
    ...span(-180, 150).filter((l) => l % 30 === 0).map((lon) => span(-80, 80).map((lat) => [lon, lat])),
    ...[-60, -30, 0, 30, 60].map((lat) => span(-180, 180).map((lon) => [lon, lat])),
  ],
};

export type EarthLayers = { land: string; ice: string; clouds: string; grid: string };

/**
 * Path data for the Earth seen with longitude `lon` at the centre (degrees; EARTH.REST_LON is the resting pose).
 * Real rotation is eastward, so to spin it, *decrease* lon over time. `cloudShift` moves the clouds east (degrees)
 * relative to the ground, for an optional slow weather drift. `grid` is a stroke (1 viewBox unit), the rest fills.
 */
export function earthLayers(lon: number = EARTH.REST_LON, cloudShift = 0): EarthLayers {
  const { filled, stroked } = projector(lon);
  return {
    land: filled(LAND_G),
    ice: filled(ICE_G),
    clouds: filled(shifted(cloudShift)),
    grid: stroked(GRID),
  };
}

/** Standalone SVG of the Earth at `lon` (the static nyko-earth.svg is earthSvg()). */
export function earthSvg(lon: number = EARTH.REST_LON, comment = ''): string {
  const L = earthLayers(lon), E = EARTH;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-64 -64 128 128" width="256" height="256"><title>NYKO Earth</title>
${comment}<defs>
  <linearGradient id="earth-ocean" x1="-42" y1="-42" x2="42" y2="42" gradientUnits="userSpaceOnUse">
    <stop offset="0" stop-color="${E.ocean[0]}"/><stop offset="1" stop-color="${E.ocean[1]}"/>
  </linearGradient>
  <linearGradient id="earth-ice" x1="0" y1="-60" x2="0" y2="-30" gradientUnits="userSpaceOnUse">
    <stop offset="0" stop-color="${E.ice[0]}"/><stop offset="1" stop-color="${E.ice[1]}"/>
  </linearGradient>
</defs>
<g id="ocean"><circle r="${E.R}" fill="url(#earth-ocean)"/></g>
<g id="grid"><path fill="none" stroke="${E.grid}" stroke-opacity="${E.gridAlpha}" stroke-width="1" d="${L.grid}"/></g>
<g id="land"><path fill="${E.land}" d="${L.land}"/></g>
<g id="ice"><path fill="url(#earth-ice)" d="${L.ice}"/></g>
<g id="clouds"><path fill="${E.cloud}" d="${L.clouds}"/></g>
</svg>
`;
}
